{
	"$schema": "https://schemas.wp.org/trunk/theme.json",
	"version": 3,
	"title": "Ciemny",
	"settings": {
		"color": {
			"palette": [
				{ "slug": "base", "color": "#121212", "name": "Tło" },
				{ "slug": "contrast", "color": "#f2f2f2", "name": "Tekst" },
				{ "slug": "primary", "color": "#7cc4e0", "name": "Kolor marki" },
				{ "slug": "primary-dark", "color": "#a9dcee", "name": "Kolor marki (hover)" },
				{ "slug": "accent", "color": "#ffb27a", "name": "Akcent" },
				{ "slug": "surface", "color": "#1e2a30", "name": "Powierzchnia" },
				{ "slug": "muted", "color": "#b8c2ca", "name": "Tekst pomocniczy" }
			]
		}
	},
	"styles": {
		"color": {
			"background": "var(--wp--preset--color--base)",
			"text": "var(--wp--preset--color--contrast)"
		},
		"elements": {
			"button": {
				"color": { "text": "var(--wp--preset--color--base)" },
				":hover": { "color": { "text": "var(--wp--preset--color--base)" } }
			}
		}
	}
}

{
	"$schema": "https://schemas.wp.org/trunk/theme.json",
	"version": 3,
	"settings": {
		"appearanceTools": true,
		"layout": { "contentSize": "720px", "wideSize": "1180px" },
		"color": {
			"defaultPalette": false,
			"defaultGradients": false,
			"palette": [
				{ "slug": "base", "color": "#ffffff", "name": "Tło" },
				{ "slug": "contrast", "color": "#1a1a1a", "name": "Tekst" },
				{ "slug": "primary", "color": "#0b5d7a", "name": "Kolor marki" },
				{ "slug": "primary-dark", "color": "#083f55", "name": "Kolor marki ciemny" },
				{ "slug": "accent", "color": "#9a3d00", "name": "Akcent" },
				{ "slug": "surface", "color": "#eaf4f7", "name": "Powierzchnia" },
				{ "slug": "muted", "color": "#4a5560", "name": "Tekst pomocniczy" }
			]
		},
		"typography": {
			"defaultFontSizes": false,
			"fluid": false,
			"fontFamilies": [
				{
					"slug": "system",
					"name": "Systemowa (bez zewnętrznych fontów)",
					"fontFamily": "system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif"
				},
				{
					"slug": "headings",
					"name": "Nagłówki (systemowa, pogrubiona)",
					"fontFamily": "\"Segoe UI\", system-ui, -apple-system, Roboto, \"Helvetica Neue\", Arial, sans-serif"
				}
			],
			"fontSizes": [
				{ "slug": "small", "size": "0.9375rem", "name": "Mały" },
				{ "slug": "medium", "size": "1.125rem", "name": "Średni" },
				{ "slug": "large", "size": "1.5rem", "name": "Duży" },
				{ "slug": "x-large", "size": "clamp(1.75rem, 1.2rem + 2.5vw, 3rem)", "name": "Tytuł" },
				{ "slug": "xx-large", "size": "clamp(2rem, 1.4rem + 3.2vw, 3.5rem)", "name": "Tytuł główny" }
			]
		},
		"spacing": {
			"defaultSpacingSizes": false,
			"units": [ "px", "rem", "%", "vw" ],
			"spacingSizes": [
				{ "slug": "20", "size": "0.5rem", "name": "XS" },
				{ "slug": "30", "size": "1rem", "name": "S" },
				{ "slug": "40", "size": "1.5rem", "name": "M" },
				{ "slug": "50", "size": "clamp(2rem, 1rem + 3vw, 3rem)", "name": "L" },
				{ "slug": "60", "size": "clamp(3rem, 2rem + 4vw, 5rem)", "name": "XL" }
			]
		}
	},
	"styles": {
		"color": {
			"background": "var(--wp--preset--color--base)",
			"text": "var(--wp--preset--color--contrast)"
		},
		"typography": {
			"fontFamily": "var(--wp--preset--font-family--system)",
			"fontSize": "var(--wp--preset--font-size--medium)",
			"lineHeight": "1.65"
		},
		"spacing": {
			"blockGap": "1.5rem",
			"padding": { "left": "var(--wp--preset--spacing--30)", "right": "var(--wp--preset--spacing--30)" }
		},
		"elements": {
			"link": {
				"color": { "text": "var(--wp--preset--color--primary)" },
				"typography": { "textDecoration": "underline" },
				":hover": { "color": { "text": "var(--wp--preset--color--primary-dark)" } }
			},
			"button": {
				"color": {
					"background": "var(--wp--preset--color--primary)",
					"text": "var(--wp--preset--color--base)"
				},
				"typography": { "fontWeight": "700", "textDecoration": "none" },
				"border": { "radius": "6px" },
				"spacing": { "padding": { "top": "0.75rem", "bottom": "0.75rem", "left": "1.5rem", "right": "1.5rem" } },
				":hover": {
					"color": {
						"background": "var(--wp--preset--color--primary-dark)",
						"text": "var(--wp--preset--color--base)"
					}
				}
			},
			"heading": {
				"typography": { "fontFamily": "var(--wp--preset--font-family--headings)", "fontWeight": "700", "lineHeight": "1.2" },
				"color": { "text": "var(--wp--preset--color--primary-dark)" }
			},
			"h1": { "typography": { "fontSize": "var(--wp--preset--font-size--xx-large)" } },
			"h2": { "typography": { "fontSize": "var(--wp--preset--font-size--x-large)" } },
			"h3": { "typography": { "fontSize": "var(--wp--preset--font-size--large)" } }
		},
		"blocks": {
			"core/site-title": {
				"typography": { "fontWeight": "800", "fontSize": "var(--wp--preset--font-size--large)" },
				"elements": { "link": { "typography": { "textDecoration": "none" } } }
			},
			"core/navigation": {
				"typography": { "fontSize": "var(--wp--preset--font-size--medium)" },
				"elements": { "link": { "typography": { "textDecoration": "none" } } }
			},
			"core/quote": {
				"border": { "left": { "color": "var(--wp--preset--color--accent)", "width": "4px", "style": "solid" } },
				"spacing": { "padding": { "left": "var(--wp--preset--spacing--30)" } }
			}
		},
		"css": ":where(a, button, input, select, textarea, summary):focus-visible{outline:3px solid var(--wp--preset--color--contrast);outline-offset:3px}html{scroll-padding-top:6rem}.wp-block-navigation-item__content,.wp-block-social-link a,.wp-element-button{min-height:24px;min-width:24px}.wp-block-navigation-item__content{padding-block:.5rem}.mf-header{padding-block:.5rem;position:sticky;top:0;z-index:100;background:var(--wp--preset--color--base);border-bottom:1px solid var(--wp--preset--color--surface)}.skip-link:focus{position:fixed;top:1rem;left:1rem;z-index:1000;padding:.75rem 1rem;background:var(--wp--preset--color--base);color:var(--wp--preset--color--contrast)}@media (max-width:600px){.wp-block-columns{gap:1rem}.mf-hero{min-height:auto}}@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}@media (forced-colors:active){.wp-block-button__link{border:2px solid ButtonText}}.mf-footer a{color:inherit}.mf-footer :where(a,button):focus-visible{outline-color:currentColor}.mf-footer{padding-block:var(--wp--preset--spacing--50)}.mf-hero,.mf-uslugi,.mf-opinie{padding-block:var(--wp--preset--spacing--60)}.mf-hero .wp-block-cover__inner-container{color:var(--wp--preset--color--contrast)}.mf-hero :is(h1,h2):not(.has-text-color){color:var(--wp--preset--color--primary-dark)}.wpcf7 label{display:block;font-weight:600;margin-bottom:1rem}.wpcf7 input[type=text],.wpcf7 input[type=email],.wpcf7 textarea{display:block;box-sizing:border-box;width:100%;max-width:100%;margin-top:.35rem;padding:.65rem .75rem;border:2px solid var(--wp--preset--color--muted);border-radius:6px;font:inherit;background:var(--wp--preset--color--base);color:var(--wp--preset--color--contrast)}.wpcf7 input[type=submit]{min-height:44px;padding:.75rem 1.5rem;border:0;border-radius:6px;font:inherit;font-weight:700;cursor:pointer;background:var(--wp--preset--color--primary);color:var(--wp--preset--color--base)}.wpcf7 input[type=submit]:hover{background:var(--wp--preset--color--primary-dark)}.wpcf7 .wpcf7-not-valid-tip{color:var(--wp--preset--color--accent);font-weight:600}"
	},
	"templateParts": [
		{ "name": "header", "title": "Nagłówek", "area": "header" },
		{ "name": "footer", "title": "Stopka", "area": "footer" }
	],
	"customTemplates": []
}
